const money = value => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);
function renderSpendBreakdown(){
  const donut=document.querySelector('#spend-donut'),totalLabel=document.querySelector('#spend-donut-total'),legend=document.querySelector('#spend-legend');
  if(!donut||!totalLabel||!legend)return;
  const categories=Object.entries(expenses.reduce((groups,item)=>{groups[item.category]=(groups[item.category]||0)+item.committed;return groups;},{})).sort((a,b)=>b[1]-a[1]);
  const total=categories.reduce((sum,[,amount])=>sum+amount,0),palette=['#5f8b6e','#ddaa9e','#c9aa73','#a8bac2','#aa91af','#e4e8e2'];
  totalLabel.innerHTML=`${money(total)}<small>committed</small>`;
  if(!total){donut.style.background='conic-gradient(#e7ece5 0 100%)';legend.innerHTML='<p class="empty-state">Add expenses to see category totals.</p>';return;}
  let position=0;
  donut.style.background=`conic-gradient(${categories.map(([,amount],index)=>{const start=position,end=position+(amount/total)*100;position=end;return `${palette[index%palette.length]} ${start}% ${end}%`;}).join(', ')})`;
  legend.innerHTML=categories.map(([category,amount],index)=>`<p><i style="background:${palette[index%palette.length]}"></i>${category}<b>${money(amount)}</b></p>`).join('');
}
