function setExpenseStatus(expense){expense.status=expense.paid>=expense.committed?'Paid':expense.paid?'Partial':'Planned';}
function populatePaymentExpenses(selectedName){const select=document.querySelector('#payment-expense');select.innerHTML=expenses.map(item=>`<option value="${item.name}">${item.name} — ${money(Math.max(item.committed-item.paid,0))} owed</option>`).join('');select.value=selectedName || expenses.find(item=>item.committed-item.paid>0)?.name || expenses[0]?.name;}
function openPaymentModal(){editingPaymentIndex=null;document.querySelector('#payment-form').reset();document.querySelector('#payment-modal h2').textContent='Record a payment';document.querySelector('#payment-modal .add-button').textContent='Save payment';populatePaymentExpenses();document.querySelector('[name="date"]').value=new Date().toISOString().slice(0,10);document.querySelector('#payment-modal').showModal();}
function editPayment(index){const payment=payments[index], form=document.querySelector('#payment-form');editingPaymentIndex=index;form.reset();document.querySelector('#payment-modal h2').textContent='Edit payment';document.querySelector('#payment-modal .add-button').textContent='Save changes';populatePaymentExpenses(payment.expense);form.elements.amount.value=payment.amount;form.elements.paidBy.value=payment.paidBy;form.elements.date.value=payment.date;document.querySelector('#payment-modal').showModal();}
function deletePayment(index){const payment=payments[index];if(!window.confirm(`Delete ${money(payment.amount)} payment for “${payment.expense}”?`))return;const expense=expenses.find(item=>item.name===payment.expense);if(expense){expense.paid=Math.max(0,expense.paid-payment.amount);setExpenseStatus(expense);}payments.splice(index,1);localStorage.setItem('everAfterExpenses',JSON.stringify(expenses));localStorage.setItem('everAfterPayments',JSON.stringify(payments));renderExpenses();logActivity(`Deleted ${money(payment.amount)} payment for ${payment.expense}`);}
