// Shared checklist: task data lives in PostgreSQL once the user has signed in.
function dueLabel(date) { return date ? `Due ${new Date(`${date}T12:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric'})}` : 'No due date'; }
function fromSharedTask(task) {
  return [task.title, (task.category || 'Other').toUpperCase(), dueLabel(task.due_date), task.status === 'done', task.status, (task.comments || []).map(comment => ({ id:comment.id, author:comment.author_name, authorId:comment.created_by, text:comment.body })), task.priority || 'Medium', task.assignee_name || task.assignee || 'Unassigned', task.notes || '', task.linked_vendor || '', task.due_date || '', task.id, task.position || 0, task.assignee_user_id || null, task.attachments || []];
}
async function loadSharedTasks() {
  if (!sharedTaskWorkspaceId || !window.everAfterApi) return;
  const result = await window.everAfterApi(`/api/weddings/${sharedTaskWorkspaceId}/tasks`);
  tasks = result.tasks.map(fromSharedTask);
  renderTasks();
  loadSharedActivity().catch(error=>console.error('Could not refresh shared activity',error));
}
async function saveSharedTask(task, existingTask) {
  const assigneeUserId = taskAssignees.find(member => member.id === task[7] || member.name === task[7])?.id || existingTask?.[14] || null;
  const payload = { title:task[0], category:task[1], priority:task[6] || 'Medium', assigneeUserId, notes:task[8] || null, linkedVendor:task[9] || null, dueDate:task[10] || null, status:task[4] || 'todo' };
  if (existingTask?.[11]) await window.everAfterApi(`/api/weddings/${sharedTaskWorkspaceId}/tasks/${existingTask[11]}`, { method:'PATCH', body:JSON.stringify(payload) });
  else await window.everAfterApi(`/api/weddings/${sharedTaskWorkspaceId}/tasks`, { method:'POST', body:JSON.stringify(payload) });
  await loadSharedTasks();
}
async function updateSharedTask(index, changes) {
  const task = tasks[index]; if (!task?.[11]) return;
  await window.everAfterApi(`/api/weddings/${sharedTaskWorkspaceId}/tasks/${task[11]}`, { method:'PATCH', body:JSON.stringify(changes) });
  await loadSharedTasks();
}
async function persistSharedTaskOrder() {
  const positions = { todo:0, progress:0, done:0 };
  const payload = tasks.map(task => ({ id:task[11], status:task[4] || 'todo', position:positions[task[4] || 'todo']++ })).filter(task => task.id);
  await window.everAfterApi(`/api/weddings/${sharedTaskWorkspaceId}/tasks/order`, { method:'PUT', body:JSON.stringify({ tasks:payload }) });
  await loadSharedTasks();
}
function renderTasks() {
  const openTasks = tasks.map((task,index)=>({task,index})).filter(({task})=>!task[3]);
  document.querySelector('#priority-list').innerHTML = openTasks.map(({task,index}) => `<article class="priority-item"><button class="check" aria-label="Complete ${task[0]}" data-complete-task="${index}"></button><div><strong>${task[0]}</strong><small>${task[1]} · ${task[7] || 'Unassigned'} · ${task[6] || 'Medium'} priority</small></div><time>${task[2]}</time><div class="task-actions"><button data-edit-task="${index}">Edit</button><button class="danger-action" data-delete-shared-task="${index}">Delete</button></div></article>`).join('') || '<p class="empty-state">Everything is complete — enjoy the moment.</p>';
  document.querySelectorAll('[data-complete-task]').forEach(button => button.onclick = () => completeTask(Number(button.dataset.completeTask)));
  document.querySelectorAll('[data-edit-task]').forEach(button => button.onclick = () => editTask(Number(button.dataset.editTask)));
  document.querySelectorAll('[data-delete-shared-task]').forEach(button => button.onclick = () => deleteTask(Number(button.dataset.deleteSharedTask)));
  renderKanban();
}
function renderKanban() {
  const board = document.querySelector('.task-board'), columns=[['todo','DO NEXT'],['progress','IN PROGRESS'],['done','DONE']];
  board.innerHTML = columns.map(([status,label]) => {
    const cards=tasks.map((task,index)=>({task,index})).filter(({task})=>(task[4]||'todo')===status);
    return `<div class="board-column" data-kanban-column="${status}"><h3>${label} <b>${cards.length}</b></h3><div class="kanban-dropzone">${cards.map(({task,index}) => { const comments=task[5]||[]; return `<article class="task-card ${status==='done'?'done':''}" draggable="true" data-kanban-task="${index}"><span class="tag">${task[1]} · ${task[6] || 'Medium'}</span><h4>${task[0]}</h4><p>${task[2]} · ${task[7] || 'Unassigned'}${task[9]?` · ${task[9]}`:''}</p>${task[8]?`<small class="task-note">${task[8]}</small>`:''}<div class="kanban-actions"><button data-comment-task="${index}">Comment${comments.length?` (${comments.length})`:''}</button><button data-edit-kanban-task="${index}">Edit</button><button class="danger-action" data-delete-kanban-task="${index}">Delete</button></div>${comments.map((comment,commentIndex)=>`<p class="task-comment"><b>${comment.author}</b> ${comment.text}<span>${canManageComment(comment)?`<button data-edit-task-comment="${index}:${commentIndex}">Edit</button><button data-delete-task-comment="${index}:${commentIndex}">Delete</button>`:''}</span></p>`).join('')}</article>`; }).join('') || '<p class="empty-state">Drop a task here</p>'}</div></div>`;
  }).join('');
  document.querySelectorAll('[data-kanban-task]').forEach(card => {
    card.addEventListener('dragstart', event => { if (event.target.closest('button')) return event.preventDefault(); event.dataTransfer.setData('text/plain',card.dataset.kanbanTask); card.classList.add('dragging'); });
    card.addEventListener('dragend', () => card.classList.remove('dragging'));
  });
  document.querySelectorAll('[data-comment-task]').forEach(button=>button.onclick=()=>openTaskCommentModal(Number(button.dataset.commentTask)));
  document.querySelectorAll('[data-edit-kanban-task]').forEach(button=>button.onclick=()=>editTask(Number(button.dataset.editKanbanTask)));
  document.querySelectorAll('[data-delete-kanban-task]').forEach(button=>button.onclick=()=>deleteTask(Number(button.dataset.deleteKanbanTask)));
  document.querySelectorAll('[data-edit-task-comment]').forEach(button=>button.onclick=()=>editTaskComment(...button.dataset.editTaskComment.split(':').map(Number)));
  document.querySelectorAll('[data-delete-task-comment]').forEach(button=>button.onclick=()=>deleteTaskComment(...button.dataset.deleteTaskComment.split(':').map(Number)));
  document.querySelectorAll('[data-kanban-column]').forEach(column=>{ column.addEventListener('dragover',event=>{event.preventDefault();column.classList.add('drag-over');}); column.addEventListener('dragleave',()=>column.classList.remove('drag-over')); column.addEventListener('drop',()=>column.classList.remove('drag-over')); });
}
function canManageComment(comment) { return window.everAfterWorkspaceRole === 'owner' || comment.authorId === window.everAfterUser?.id; }
async function completeTask(index) { try { if (sharedTasksActive) await updateSharedTask(index,{status:'done'}); else { tasks[index][3]=true; tasks[index][4]='done'; localStorage.setItem('everAfterTasks',JSON.stringify(tasks)); renderTasks(); } } catch (error) { window.alert(error.message); } }
