function openTaskCommentModal(index) { activeTaskCommentIndex=index; editingTaskCommentIndex=null; const form=document.querySelector('#task-comment-form'); form.reset(); form.elements.author.value=window.everAfterUser?.display_name || 'You'; document.querySelector('#task-comment-title').textContent='Add a comment'; document.querySelector('#save-task-comment').textContent='Post comment'; document.querySelector('#task-comment-modal').showModal(); }
function editTaskComment(taskIndex,commentIndex) { activeTaskCommentIndex=taskIndex; editingTaskCommentIndex=commentIndex; const comment=tasks[taskIndex][5][commentIndex],form=document.querySelector('#task-comment-form'); form.elements.author.value=comment.author; form.elements.text.value=comment.text; document.querySelector('#task-comment-title').textContent='Edit comment'; document.querySelector('#save-task-comment').textContent='Save changes'; document.querySelector('#task-comment-modal').showModal(); }
